effect.shader:
const vec3 DEFASAGEM = vec3(0.0, 2.094395, 4.188790); // 0°, 120°, 240°

/** Arco-íris suave de três cossenos defasados. */
vec3 arcoIris(float fase) {
    return 0.5 + 0.5 * cos(6.2831853 * fase + DEFASAGEM);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y) * scale;
    float t = acTime * speed;

    // Quatro senos: horizontal, vertical, diagonal, radial.
    float campo = sin(p.x + t)
                + sin(p.y + t * 1.3)
                + sin((p.x + p.y) * 0.7 + t * 0.9)
                + sin(length(p - scale * 0.5) + t * 1.5);

    // Normaliza o campo de [-4, 4] pra [0, 1] e envia pra rampa.
    float fase = campo * 0.125 + 0.5 + colorShift;
    vec3 plasma = arcoIris(fase);

    vec3 cor = mix(original.rgb, plasma, blend);

    fragColor = vec4(cor, original.a);
}
